-- ============================================================================
-- 0050_ref_data -- global reference data: currencies and countries.
--
-- A NEW SCHEMA, not `platform`. Everything in `platform` is either tenant-scoped or a
-- provider's view of the world; a currency and a country are neither — they are facts that
-- predate any firm and belong to no one. Keeping them out of `platform` means nobody has to ask
-- whether a row needs a tenant_id, which is the question that made products global by accident
-- in 0002 (fixed in 0042).
--
-- Data lifted from the reference implementation's seed (graphene-platform pkgs/db/seed.sql), so
-- the two systems agree on codes, symbols and EEA membership rather than diverging on a detail
-- like whether the pound sign is stored or derived.
--
-- The seed is ON CONFLICT DO NOTHING: a migration that cannot be re-run against a
-- partially-seeded database is one that has to be repaired by hand.
-- ============================================================================

CREATE SCHEMA IF NOT EXISTS ref;
GRANT USAGE ON SCHEMA ref TO authenticated, service_role;

CREATE TABLE ref.currencies (
  code      text PRIMARY KEY,
  currency  text,
  country   text,
  symbol    text,
  -- The symbol's codepoints, as the reference implementation stores them: a renderer that cannot
  -- rely on the font having the glyph needs them, and deriving them back from `symbol` is lossy
  -- for the multi-codepoint cases.
  hex_codes text[]
);

CREATE TABLE ref.countries (
  code      text PRIMARY KEY,
  name      text NOT NULL,
  adjective text,
  in_eea    boolean NOT NULL DEFAULT false,
  -- Accepted identity documents and their patterns, per country -- what an onboarding form
  -- validates a passport or national id against.
  identifiers jsonb NOT NULL DEFAULT '[]'::jsonb
);

CREATE INDEX countries_in_eea_idx ON ref.countries (in_eea) WHERE in_eea;

-- Readable by every logged-in principal and un-scoped, the treatment platform.instruments gets
-- (0041): an ISIN is not tenant data and neither is the euro. RLS is enabled with a permissive
-- read so the schema-invariant test's "every table has RLS" rule holds without pretending this
-- data is private.
ALTER TABLE ref.currencies ENABLE ROW LEVEL SECURITY;
ALTER TABLE ref.currencies FORCE ROW LEVEL SECURITY;
CREATE POLICY currencies_read ON ref.currencies FOR SELECT TO authenticated USING (true);

ALTER TABLE ref.countries ENABLE ROW LEVEL SECURITY;
ALTER TABLE ref.countries FORCE ROW LEVEL SECURITY;
CREATE POLICY countries_read ON ref.countries FOR SELECT TO authenticated USING (true);

GRANT SELECT ON ref.currencies, ref.countries TO authenticated;
GRANT ALL ON ref.currencies, ref.countries TO service_role;

-- The migrator owns these tables but is subject to FORCE ROW LEVEL SECURITY and is not
-- bypassrls, so the seed INSERTs are rejected without this (precedent: 0023, 0041, 0044, 0046).
SET LOCAL ROLE service_role;

ON CONFLICT (code) DO NOTHING;

ON CONFLICT (code) DO NOTHING;

RESET ROLE;
